'use strict';

class GaugeCard {
  constructor(surfaceId, color, x = 5, y = 5) {
    if (typeof surfaceId !== 'string' || surfaceId.trim() === '') {
      throw new TypeError('surfaceId must be a non-empty string');
    }
    if (typeof color !== 'string' || color.trim() === '') {
      throw new TypeError('color must be a non-empty string');
    }
    if (typeof x !== 'number' || !Number.isFinite(x) || typeof y !== 'number' || !Number.isFinite(y)) {
      throw new TypeError('coordinates must be finite numbers');
    }
    this._surfaceId = surfaceId;
    this._color = color;
    this._x = x;
    this._y = y;
    this._message = null;
  }

  redraw(color) {
    if (color !== undefined) {
      if (typeof color !== 'string' || color.trim() === '') {
        throw new TypeError('color must be a non-empty string');
      }
      this._color = color;
    }
    return this.commands();
  }

  setMessage(message, token, font = '12pt sans-serif') {
    if (typeof message !== 'string' || typeof token !== 'string') {
      throw new TypeError('message and token must be strings');
    }
    if (typeof font !== 'string' || font.trim() === '') {
      throw new TypeError('font must be a non-empty string');
    }
    if (this._message === null) this._message = { message, token, font };
    return this.commands();
  }

  commands() {
    const result = [
      { type: 'shadow', blur: 6, offsetX: 2, offsetY: 2 },
      { type: 'card', surfaceId: this._surfaceId, color: this._color, x: this._x, y: this._y }
    ];
    if (this._message !== null) {
      result.push({
        type: 'text',
        message: this._message.message,
        token: this._message.token,
        font: this._message.font,
        x: this._x + 8,
        y: this._y + 20
      });
    }
    return result;
  }
}

module.exports = GaugeCard;

