'use strict';
const assert = require('node:assert');
const GaugeCard = require('./solution');
assert.strictEqual(typeof GaugeCard, 'function');
assert.throws(() => new GaugeCard('', 'red'), TypeError);
assert.throws(() => new GaugeCard('s', ''), TypeError);
assert.throws(() => new GaugeCard('s', 'red', NaN), TypeError);
assert.throws(() => new GaugeCard('s', 'red', 1, Infinity), TypeError);

const gauge = new GaugeCard('surface', 'red', undefined, 0);
assert.deepStrictEqual(gauge.commands(), [
  { type: 'shadow', blur: 6, offsetX: 2, offsetY: 2 },
  { type: 'card', surfaceId: 'surface', color: 'red', x: 5, y: 0 }
]);
assert.deepStrictEqual(gauge.redraw(), [
  { type: 'shadow', blur: 6, offsetX: 2, offsetY: 2 },
  { type: 'card', surfaceId: 'surface', color: 'red', x: 5, y: 0 }
]);
assert.throws(() => gauge.redraw(''), TypeError);
assert.throws(() => gauge.redraw(1), TypeError);
assert.strictEqual(gauge.redraw('blue')[1].color, 'blue');

assert.throws(() => gauge.setMessage(1, 't'), TypeError);
assert.throws(() => gauge.setMessage('m', null), TypeError);
assert.throws(() => gauge.setMessage('m', 't', ''), TypeError);
const withEmptyMessage = gauge.setMessage('', '', undefined);
assert.deepStrictEqual(withEmptyMessage, [
  { type: 'shadow', blur: 6, offsetX: 2, offsetY: 2 },
  { type: 'card', surfaceId: 'surface', color: 'blue', x: 5, y: 0 },
  { type: 'text', message: '', token: '', font: '12pt sans-serif', x: 13, y: 20 }
]);
assert.deepStrictEqual(gauge.setMessage('Ready', 'abc', '10px serif')[2], {
  type: 'text', message: 'Ready', token: 'abc', font: '10px serif', x: 13, y: 20
});

const c1 = gauge.commands();
const c2 = gauge.commands();
assert.notStrictEqual(c1, c2);
for (let i = 0; i < c1.length; i++) assert.notStrictEqual(c1[i], c2[i]);
c1.length = 0;
c2[0].blur = 100;
c2[1].color = 'changed';
c2[2].message = 'changed';
assert.deepStrictEqual(gauge.commands(), [
  { type: 'shadow', blur: 6, offsetX: 2, offsetY: 2 },
  { type: 'card', surfaceId: 'surface', color: 'blue', x: 5, y: 0 },
  { type: 'text', message: 'Ready', token: 'abc', font: '10px serif', x: 13, y: 20 }
]);

